// More straightforward thread mapping and computation

extern "C" __global__ 
void int4_gemm_fused_simple(
    const __half* __restrict__ x,      // Input: (batch_seq_len, K)
    const uint8_t* __restrict__ w_packed, // Packed weights: (N, K/2) - 2 INT4 values per byte
    const __half* __restrict__ scales, // Scales: (N, num_groups)
    __half* __restrict__ y,            // Output: (batch_seq_len, N)
    int batch_seq_len,                 // Number of rows in X and Y
    int K,                            // Number of columns in X, rows in W
    int N,                            // Number of columns in W, columns in Y
    int num_groups,                   // K / group_size
    int group_size                    // Size of each quantization group
) {
    // Block tile sizes
    const int BM = 64;    // Block size along M (rows)
    const int BN = 64;    // Block size along N (columns)

    // Thread configuration
    int tid = threadIdx.x;
    int thread_row = tid / 4;     // Each thread handles multiple rows
    int thread_col = tid % 4;     // Each thread handles multiple columns

    // Block position in output matrix
    int block_row = blockIdx.x * BM;
    int block_col = blockIdx.y * BN;

    // Don't process out of bounds
    if (block_row >= batch_seq_len || block_col >= N) return;

    // Each thread accumulates results for a subset of the output tile
    float accum[8] = {0.0f};  // Each thread computes 8 output elements

    // Loop over K dimension - the key to GEMM
    for (int k = 0; k < K; k++) {
        // Load input X value for this k position
        // All threads in block load from same row but different columns
        int x_row = block_row + thread_row / 2;  // Row position
        int x_col = k;                           // Current column in K

        if (x_row >= batch_seq_len) continue;

        __half x_h = x[x_row * K + x_col];
        float x_f = __half2float(x_h);

        // Skip zero inputs for efficiency
        if (x_f == 0.0f) continue;

        // For each output column this thread is responsible for
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                // Calculate output column
                int out_col = block_col + thread_col * 16 + i * 8 + j * 4;
                if (out_col >= N) continue;

                // Load the INT4 weight for this position
                // Weight matrix shape: (N, K/2) packed format
                int w_row = out_col;                    // Row in weight matrix
                int w_col_packed = k / 2;               // Column in packed format

                if (w_col_packed >= K/2) continue;

                // Load packed byte containing 2 INT4 values
                uint8_t packed = w_packed[w_row * (K/2) + w_col_packed];

                // Determine if we need low or high nibble
                // k % 2 == 0 -> low nibble (bits 0-3)
                // k % 2 == 1 -> high nibble (bits 4-7)
                int w_int;
                if (k % 2 == 0) {
                    w_int = packed & 0x0F;  // Low nibble
                } else {
                    w_int = (packed >> 4) & 0x0F;  // High nibble
                }

                // Apply symmetric dequantization: w_dequant = scale * (w_int - 8)
                // where 8 is the implicit zero-point (center of [0, 15])
                int k_group = k / group_size;
                float scale = __half2float(scales[w_row * num_groups + k_group]);
                float w_dequant = scale * (static_cast<float>(w_int) - 8.0f);

                // Accumulate
                accum[i*4 + j*2 + 0] += x_f * w_dequant;
            }
        }
    }

    // Store results back to output
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            int out_col = block_col + thread_col * 16 + i * 8 + j * 4;
            if (out_col < N) {
                int out_row = block_row + thread_row / 2;
                if (out_row < batch_seq_len) {
                    y[out_row * N + out_col] = __float2half(accum[i*4 + j*2 + 0]);
                }
            }
        }
    }
