            // Get scale
            int k_group = k / group_size;
            float scale = __half2float(scales[col * num_groups + k_group]);

            // Dequantize
            float w_dequant = scale * (static_cast<float>(w_int) - 8.0f);

            sum += x_val * w_dequant;
        }

        // Store result
