    int batch_seq_len,                 // Number of rows in X and Y
    int K,                            // Number of columns in X, rows in W
    int N,                            // Number of columns in W, columns in Y
    int num_groups,                   // K / group_size
    int group_size                    // Size of each quantization group
) {
    // Block tile sizes
    const int BM = 64;    // Block size along M (rows)
    const int BN = 64;    // Block size along N (columns)

    // Thread configuration
    int tid = threadIdx.x;
    int thread_row = tid / 4;     // Each thread handles multiple rows
    int thread_col = tid % 4;     // Each thread handles multiple columns

    // Block position in output matrix
    int block_row = blockIdx.x * BM;
    int block_col = blockIdx.y * BN;

    // Don't process out of bounds
    if (block_row >= batch_seq_len || block_col >= N) return;

    // Each thread accumulates results for a subset of the output tile
    float accum[8] = {0.0f};  // Each thread computes 8 output elements

    // Loop over K dimension - the key to GEMM
    for (int k = 0; k < K; k++) {
        // Load input X value for this k position
        // All threads in block load from same row but different columns
        int x_row = block_row + thread_row / 2;  // Row position
        int x_col = k;                           // Current column in K

        if (x_row >= batch_seq_len) continue;

        __half x_h = x[x_row * K + x_col];
        float x_f = __half2float(x_h);

        // Skip zero inputs for efficiency
        if (x_f == 0.0f) continue;

